69| <div id="wrap">
70|   <div id="hud">
71|     <div id="counter">Poissons : 0</div>
72|     <button id="clearBtn">Vider le bocal</button>
73|   </div>
74|   <canvas id="game"></canvas>
75| </div>
76| <script>
77| const CARTRIDGE = {
78|   send(type, payload = {}) {
79|     window.parent.postMessage(
80|       { source: "cartridge", v: 1, type, payload },
81|       "*",
82|     );
83|   },
84| };
85| </script>
86| <script>
87| (function () {
88|   const canvas = document.getElementById("game");
89|   const ctx = canvas.getContext("2d");
90|   const counterEl = document.getElementById("counter");
91|   const clearBtn = document.getElementById("clearBtn");
92| 
93|   let dpr = Math.max(1, window.devicePixelRatio || 1);
94|   let W = 0, H = 0;
95| 
96|   // paper-cut palette
97|   const COLORS = {
98|     bg: "#f4ecd8",
99|     layer: "#e07a5f",
100|     accent: "#3d405b",
101|     highlight: "#81b29a"
102|   };
103| 
104|   const fishColors = ["#e07a5f", "#81b29a", "#3d405b", "#f2cc8f", "#c98474"];
105| 
106|   let paused = false;
107|   let running = false;
108|   let started = false;
109| 
110|   // seeded jitter helper so shapes don't flicker
111|   function seededRandom(seed) {
112|     let s = seed % 2147483647;
113|     if (s <= 0) s += 2147483646;
114|     return function () {
115|       s = (s * 16807) % 2147483647;
116|       return (s - 1) / 2147483646;
117|     };
118|   }
119| 
120|   const fish = []; // {x,y,baseY,angle,speed,phase,color,size,jitterSeed}
121|   let tally = 0;
122| 
123|   function jarBounds() {
124|     // jar occupies central area
125|     const margin = Math.min(W, H) * 0.08;
126|     const jarW = W - margin * 2;
127|     const jarH = H * 0.62;
128|     const jarX = margin;
129|     const jarY = H * 0.18;
130|     return { x: jarX, y: jarY, w: jarW, h: jarH };
131|   }
132| 
133|   function resize() {
134|     dpr = Math.max(1, window.devicePixelRatio || 1);
135|     W = window.innerWidth;
136|     H = window.innerHeight;
137|     canvas.width = Math.floor(W * dpr);
138|     canvas.height = Math.floor(H * dpr);
139|     canvas.style.width = W + "px";
140|     canvas.style.height = H + "px";
141|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
142|   }
143|   window.addEventListener("resize", resize);
144|   resize();
145| 
146|   function makeFish(x, y) {
147|     const rnd = seededRandom(Math.floor(x * 1000 + y * 7 + tally * 91 + 1));
148|     const size = 16 + rnd() * 10;
149|     const color = fishColors[Math.floor(rnd() * fishColors.length)];
150|     return {
151|       x, y,
152|       baseY: y,
153|       angle: rnd() * Math.PI * 2,
154|       dir: rnd() > 0.5 ? 1 : -1,
155|       speed: 0.4 + rnd() * 0.6,
156|       phase: rnd() * Math.PI * 2,
157|       wobble: 6 + rnd() * 6,
158|       color,
159|       size,
160|       seed: Math.floor(rnd() * 100000)
161|     };
162|   }
163| 
164|   function place(x, y) {
165|     const f = makeFish(x, y);
166|     fish.push(f);
167|     tally += 1;
168|     counterEl.textContent = "Poissons : " + tally;
169|     CARTRIDGE.send("score", { value: tally });
170|   }
171| 
172|   // Single clear-the-table function: used by both the visible button
173|   // and the host "reset" command.
174|   function clearTable() {
175|     fish.length = 0;
176|     tally = 0;
177|     counterEl.textContent = "Poissons : 0";
178|     CARTRIDGE.send("score", { value: 0 });
179|     started = false;
180|     running = false;
181|     draw();
182|   }
183| 
184|   clearBtn.addEventListener("click", function (e) {
185|     e.stopPropagation();
186|     clearTable();
187|   });
188| 
189|   function jitterPoint(x, y, seed, amt) {
190|     const rnd = seededRandom(seed);
191|     return [x + (rnd() - 0.5) * amt * 2, y + (rnd() - 0.5) * amt * 2];
192|   }
193| 
194|   function drawRoundedJitterRect(x, y, w, h, r, seed, amt) {
195|     const pts = [
196|       [x + r, y],
197|       [x + w - r, y],
198|       [x + w, y + r],
199|       [x + w, y + h - r],
200|       [x + w - r, y + h],
201|       [x + r, y + h],
202|       [x, y + h - r],
203|       [x, y + r]
204|     ];
205|     ctx.beginPath();
206|     for (let i = 0; i < pts.length; i++) {
207|       const [jx, jy] = jitterPoint(pts[i][0], pts[i][1], seed + i, amt);
208|       if (i === 0) ctx.moveTo(jx, jy);
209|       else ctx.lineTo(jx, jy);
210|     }
211|     ctx.closePath();
212|   }
213| 
214|   function drawBackground() {
215|     ctx.fillStyle = COLORS.bg;
216|     ctx.fillRect(0, 0, W, H);
217|   }
218| 
219|   function drawTitle() {
220|     ctx.save();
221|     ctx.fillStyle = COLORS.accent;
222|     ctx.font = "bold " + Math.round(Math.min(W, H) * 0.05) + "px sans-serif";
223|     ctx.textAlign = "center";
224|     ctx.textBaseline = "middle";
225|     const pulse = 0.7 + 0.3 * Math.sin(Date.now() / 300);
226|     ctx.globalAlpha = pulse;
227|     ctx.fillText("Touchez pour commencer", W / 2, H * 0.12);
228|     ctx.globalAlpha = 1;
229|     ctx.restore();
230|   }
231| 
232|   function drawJar(bounds) {
233|     const { x, y, w, h } = bounds;
234|     // shadow layer behind jar
235|     ctx.save();
236|     ctx.shadowColor = "rgba(61,64,91,0.35)";
237|     ctx.shadowBlur = 6;
238|     ctx.shadowOffsetY = 3;
239| 
240|     // jar body - paper layer
241|     ctx.fillStyle = "#ffffff";
242|     ctx.globalAlpha = 0.55;
243|     drawRoundedJitterRect(x, y, w, h, Math.min(w, h) * 0.08, 501, 1.5);
244|     ctx.fill();
245|     ctx.globalAlpha = 1;
246|     ctx.restore();
247| 
248|     // jar rim (paper strip)
249|     ctx.save();
250|     ctx.fillStyle = COLORS.layer;
251|     ctx.shadowColor = "rgba(61,64,91,0.3)";
252|     ctx.shadowBlur = 5;
253|     ctx.shadowOffsetY = 2;
254|     const rimH = h * 0.06;
255|     drawRoundedJitterRect(x - w * 0.03, y - rimH * 0.4, w * 1.06, rimH, rimH * 0.4, 502, 1.5);
256|     ctx.fill();
257|     ctx.restore();
258| 
259|     // outline suggestion via slightly darker inner card edge (thin, not glow)
260|     ctx.save();
261|     ctx.strokeStyle = COLORS.accent;
262|     ctx.lineWidth = 1.5;
263|     ctx.globalAlpha = 0.5;
264|     drawRoundedJitterRect(x, y, w, h, Math.min(w, h) * 0.08, 501, 1.5);
265|     ctx.stroke();
266|     ctx.restore();
267|   }
268| 
269|   function drawWaterLine(bounds) {
270|     const { x, y, w, h } = bounds;
271|     const waterY = y + h * 0.12;
272|     ctx.save();
273|     ctx.fillStyle = COLORS.highlight;
274|     ctx.globalAlpha = 0.35;
275|     drawRoundedJitterRect(x + 2, waterY, w - 4, h * 0.85, Math.min(w, h) * 0.06, 777, 1.2);
276|     ctx.fill();
277|     ctx.globalAlpha = 1;
278|     ctx.restore();
279|   }
280| 
281|   function drawFishShape(f, t) {
282|     const wob = Math.sin(t * 0.002 * f.speed + f.phase) * f.wobble;
283|     const px = f.x + wob * f.dir * 0.2;
284|     const py = f.baseY + Math.sin(t * 0.0015 * f.speed + f.phase * 1.3) * 8;
285|     const size = f.size;
286|     const dir = f.dir;
287| 
288|     ctx.save();
289|     ctx.translate(px, py);
290|     ctx.scale(dir, 1);
291|     ctx.shadowColor = "rgba(61,64,91,0.3)";
292|     ctx.shadowBlur = 4;
293|     ctx.shadowOffsetY = 2;
294| 
295|     // body
296|     ctx.fillStyle = f.color;
297|     ctx.beginPath();
298|     const bodyPts = [
299|       [-size, 0],
300|       [-size * 0.3, -size * 0.55],
301|       [size * 0.7, -size * 0.3],
302|       [size, 0],
303|       [size * 0.7, size * 0.3],
304|       [-size * 0.3, size * 0.55]
305|     ];
306|     for (let i = 0; i < bodyPts.length; i++) {
307|       const [jx, jy] = jitterPoint(bodyPts[i][0], bodyPts[i][1], f.seed + i, 1.2);
308|       if (i === 0) ctx.moveTo(jx, jy);
309|       else ctx.lineTo(jx, jy);
310|     }
311|     ctx.closePath();
312|     ctx.fill();
313| 
314|     // tail
315|     ctx.beginPath();
316|     ctx.moveTo(-size, 0);
317|     ctx.lineTo(-size * 1.5, -size * 0.4);
318|     ctx.lineTo(-size * 1.5, size * 0.4);
319|     ctx.closePath();
320|     ctx.fill();
321| 
322|     // eye
323|     ctx.shadowBlur = 0;
324|     ctx.fillStyle = COLORS.accent;
325|     ctx.beginPath();
326|     ctx.arc(size * 0.55, -size * 0.05, size * 0.09, 0, Math.PI * 2);
327|     ctx.fill();
328| 
329|     ctx.restore();
330|   }
331| 
332|   function draw() {
333|     const t = Date.now();
334|     drawBackground();
335|     const bounds = jarBounds();
336|     drawWaterLine(bounds);
337| 
338|     // clip fish to jar interior
339|     ctx.save();
340|     drawRoundedJitterRect(bounds.x + 3, bounds.y + 3, bounds.w - 6, bounds.h - 6, Math.min(bounds.w, bounds.h) * 0.07, 501, 1.5);
341|     ctx.clip();
342|     for (let i = 0; i < fish.length; i++) {
343|       drawFishShape(fish[i], t + i * 37);
344|     }
345|     ctx.restore();
346| 
347|     drawJar(bounds);
348| 
349|     if (!started) {
350|       drawTitle();
351|     }
352|   }
353| 
354|   function settle() {
355|     // fish positions animate purely by time in draw(); nothing to settle physically
356|   }
357| 
358|   function insideJar(x, y) {
359|     const b = jarBounds();
360|     return x > b.x && x < b.x + b.w && y > b.y && y < b.y + b.h;
361|   }
362| 
363|   function onTap(evt) {
364|     evt.preventDefault();
365|     if (paused) return;
366|     const rect = canvas.getBoundingClientRect();
367|     const x = evt.clientX - rect.left;
368|     const y = evt.clientY - rect.top;
369| 
370|     if (!started) {
371|       started = true;
372|       running = true;
373|       CARTRIDGE.send("start");
374|       // also place a fish on first tap if inside jar
375|       if (insideJar(x, y)) place(x, y);
376|       return;
377|     }
378|     if (insideJar(x, y)) {
379|       place(x, y);
380|     }
381|   }
382| 
383|   canvas.style.touchAction = "none";
384|   canvas.addEventListener("pointerdown", onTap);
385| 
386|   window.addEventListener("message", function (event) {
387|     const data = event.data;
388|     if (!data || data.source !== "cartridge-host") return;
389|     if (data.type === "pause") paused = true;
390|     if (data.type === "resume") paused = false;
391|     if (data.type === "reset") clearTable();
392|   });
393| 
394|   function frame() {
395|     if (!paused) settle();
396|     draw();
397|     requestAnimationFrame(frame);
398|   }
399| 
400|   CARTRIDGE.send("boot", { title: "Aquarium de Papier", gameType: "toy-box", lang: "fr" });
401|   CARTRIDGE.send("start");
402|   requestAnimationFrame(frame);
403| })();
404| </script>
405| </body>
406| </html>
407|

